atom_functions:
def atoms_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def atoms_add(out,term,support_ids):
    support=atoms_unique(support_ids)
    for row in out:
        if row.get('term')==term and row.get('support_ids',[])==support:
            return
    out.append({'term':term,'support_ids':support})

def atoms_parent_label(label):
    if not isinstance(label,str) or '.' not in label:
        return ''
    return label.rsplit('.',1)[0]

def atoms_trigger_kinds(raw):
    text=raw.casefold()
    kinds=[]
    if has_any(text,['upon demand','upon request','promptly upon request','at any time upon request','so requests','request in writing','written request','request of','request by','request from']):
        kinds.append('request')
    if has_any(text,['termination of this agreement','expiration of this agreement','termination or expiration of this agreement','expiration or other termination of this agreement']):
        kinds.append('agreement_end')
    if has_any(text,['termination of the project','expiration of the project','expiration or other termination of the project']):
        kinds.append('project_end')
    if has_any(text,['termination of the business relationship','termination/expiration of the business relation','termination of the working relationship']):
        kinds.append('relationship_end')
    if has_any(text,['termination of service','service terminates']):
        kinds.append('service_end')
    if has_any(text,['business relationship is not entered','relationship is not entered','fail to enter into a business relationship']):
        kinds.append('relationship_nonformation')
    kinds=atoms_unique(kinds)
    if len(kinds)>1:
        return ['multiple_explicit']
    return kinds

def atoms_scope_for(segments,index,kind):
    segment=segments[index]
    raw=segment.get('text','')
    text=raw.casefold()
    label=segment.get('label','')
    if kind=='disposal' and atoms_trigger_kinds(raw):
        return label
    if kind=='disclosure' and has_any(text,['may disclose','may be disclosed','only to disclose','restrict access','restrict disclosure','except in confidence']):
        return label
    parent=segment.get('parent','')
    while parent:
        j=index-1
        while j>=0:
            previous=segments[j]
            if previous.get('label')==parent:
                ptext=previous.get('text','').casefold()
                if kind=='disposal' and (atoms_trigger_kinds(previous.get('text','')) or has_any(ptext,['shall immediately','return','destroy','delete','erase'])):
                    return parent
                if kind=='disclosure' and has_any(ptext,['may disclose','may be disclosed','permitted disclosure','restrict access','restrict disclosure']):
                    return parent
            j-=1
        parent=atoms_parent_label(parent)
    return label

def atoms_action_parts(raw):
    text=raw.casefold()
    returned=re.search(r'\breturn(?:ed|ing)?\b',text,re.I)
    destroyed=re.search(r'\b(?:destroy|delete|erase)(?:d|ing)?\b',text,re.I)
    out=[]
    if returned is not None and destroyed is not None:
        if returned.start()<destroyed.start():
            out.append(('return',raw[returned.start():destroyed.start()].strip()))
            out.append(('destroy',raw[destroyed.start():].strip()))
        else:
            out.append(('destroy',raw[destroyed.start():returned.start()].strip()))
            out.append(('return',raw[returned.start():].strip()))
    elif returned is not None:
        out.append(('return',raw[returned.start():].strip()))
    elif destroyed is not None:
        out.append(('destroy',raw[destroyed.start():].strip()))
    return out

def atoms_material(action_kind,raw):
    text=raw.casefold()
    copies=has_any(text,['copy','copies','reproduction','reproductions'])
    information=has_any(text,['confidential information','such confidential information','all information','such information'])
    derivatives=has_any(text,['notes','abstracts','analyses','analysis','extracts','derivative'])
    all_materials=has_any(text,['any and all materials','all materials','all documents, files'])
    if all_materials:
        kind='all_source_materials'
    elif information and copies and derivatives:
        kind='information_copies_and_derivatives'
    elif information and copies:
        kind='confidential_information_and_copies'
    elif copies and not information:
        kind='copies_only'
    elif information:
        kind='confidential_information_only'
    else:
        kind='unresolved_material'
    if has_any(text,['anyone to whom','such copies and any further copies','copies made by them']):
        owner='receiving_and_downstream_copies'
    elif has_any(text,['copies made by the receiving party','copies made by recipient']):
        owner='receiving_party_copies'
    elif copies:
        owner='all_source_copies'
    elif all_materials:
        owner='source_bounded_materials'
    else:
        owner='not_applicable'
    return (kind,owner)

def atoms_emit_disposal(segments,out,unresolved):
    actions=[]
    scopes={}
    i=0
    while i<len(segments):
        segment=segments[i]
        raw=segment.get('text','')
        text=raw.casefold()
        parts=atoms_action_parts(raw)
        relevant=bool(parts) or bool(atoms_trigger_kinds(raw))
        if relevant and has_any(text,['confidential information','such information','copies','copy','materials','documents','return','destroy','delete','erase','shall immediately']):
            scope=atoms_scope_for(segments,i,'disposal')
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disposal',raw],[segment.get('unit')])
            data=scopes.get(scope,{'units':[],'texts':[],'actions':[],'triggers':[]})
            data['units']=atoms_unique(data['units']+[segment.get('unit')])
            data['texts'].append(raw)
            for trigger_kind in atoms_trigger_kinds(raw):
                trigger=['source_disposal_trigger_atom',scope,trigger_kind,raw]
                atoms_add(out,trigger,[segment.get('unit')])
                data['triggers'].append((trigger_kind,raw,segment.get('unit')))
            for action_kind,action_raw in parts:
                key=segment.get('label','')+':'+action_kind
                material_kind,owner_kind=atoms_material(action_kind,action_raw)
                atoms_add(out,['source_disposal_action_atom',scope,key,segment.get('label',''),action_kind,action_raw],[segment.get('unit')])
                atoms_add(out,['source_disposal_material_atom',scope,key,material_kind,owner_kind,action_raw],[segment.get('unit')])
                if material_kind=='unresolved_material':
                    unresolved.append('Unresolved '+action_kind+' material in source clause '+segment.get('label',''))
                if action_kind=='destroy' and has_any(text,['confirm to','certify the destruction','confirmation of destruction']):
                    atoms_add(out,['source_disposal_qualifier_atom',scope,key,'destruction_confirmation',raw],[segment.get('unit')])
                data['actions'].append({'key':key,'kind':action_kind,'raw':action_raw,'unit':segment.get('unit'),'label':segment.get('label','')})
            scopes[scope]=data
        i+=1
    for scope,data in scopes.items():
        returns=[]
        destroys=[]
        for action in data['actions']:
            if action.get('kind')=='return':
                returns.append(action)
            if action.get('kind')=='destroy':
                destroys.append(action)
        combined=' '.join(data['texts'])
        lower=combined.casefold()
        connector_ok=False
        if returns and destroys:
            left=returns[0]
            right=destroys[0]
            if has_any(lower,['expressly authorised in writing','expressly authorized in writing','where authorised in writing','where authorized in writing']):
                connector='authorized_alternative'
                atoms_add(out,['source_disposal_qualifier_atom',scope,right.get('key'),'written_authorization',combined],data['units'])
            elif '; and' in lower or ' and  ' in lower or re.search(r'\band\s+[0-9]+(?:\.[0-9]+)+\s+(?:destroy|delete|erase)',lower,re.I) is not None:
                connector='and'
            elif ' or ' in lower:
                connector='or'
            else:
                connector='unresolved_connector'
                unresolved.append('Unresolved return/destroy connector in source scope '+scope)
            atoms_add(out,['source_disposal_connector_atom',scope,left.get('key'),right.get('key'),connector,combined],data['units'])
            connector_ok=connector!='unresolved_connector'
        elif returns:
            action=returns[0]
            atoms_add(out,['source_disposal_connector_atom',scope,action.get('key'),action.get('key'),'single_return',combined],data['units'])
            connector_ok=True
        elif destroys:
            action=destroys[0]
            atoms_add(out,['source_disposal_connector_atom',scope,action.get('key'),action.get('key'),'single_destroy',combined],data['units'])
            connector_ok=True
        materials_ok=True
        for action in data['actions']:
            material_kind,owner_kind=atoms_material(action.get('kind'),action.get('raw'))
            if material_kind=='unresolved_material':
                materials_ok=False
        if data['actions'] and data['triggers'] and connector_ok and materials_ok:
            atoms_add(out,['source_program_scope_supported',scope],data['units'])
        elif data['actions'] and not data['triggers']:
            unresolved.append('No explicit trigger found for disposal scope '+scope)

def atoms_emit_disclosure(segments,out,unresolved):
    i=0
    while i<len(segments):
        segment=segments[i]
        raw=segment.get('text','')
        text=raw.casefold()
        scope=atoms_scope_for(segments,i,'disclosure')
        parent_permission=False
        j=i-1
        while j>=0:
            if segments[j].get('label')==segment.get('parent') and has_any(segments[j].get('text','').casefold(),['may disclose','may be disclosed','permitted disclosure']):
                parent_permission=True
                break
            j-=1
        direct=has_any(text,['may disclose','may be disclosed','only to disclose','disclosed only to','restrict access','restrict disclosure','except in confidence'])
        child_permission=parent_permission and has_any(text,['only to such','only to employees','only to its employees'])
        roles=[]
        if 'employee' in text or 'staff' in text or 'personnel' in text:
            owner='controlled_entity' if has_any(text,['companies directly or indirectly owned or controlled','company controlled by','under common control']) else 'receiving_party'
            roles.append(('employee',owner))
        if 'contractor' in text:
            roles.append(('contractor','receiving_party'))
        if 'consultant' in text:
            roles.append(('consultant','receiving_party'))
        if 'agent' in text:
            roles.append(('agent','receiving_party'))
        if 'adviser' in text or 'advisor' in text:
            roles.append(('professional_adviser','receiving_party'))
        roles=atoms_unique(roles)
        if (direct or child_permission) and roles:
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disclosure_permission',raw],[segment.get('unit')])
            atoms_add(out,['source_disclosure_permission_atom',scope,segment.get('label',''),raw],[segment.get('unit')])
            for role,owner in roles:
                atoms_add(out,['source_disclosure_recipient_atom',scope,segment.get('label',''),role,owner,raw],[segment.get('unit')])
            if has_any(text,['need to know','need-to-know','bona fide need']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'need_to_know',raw],[segment.get('unit')])
            if has_any(text,['strictly necessary','extent necessary','extent absolutely necessary','disclosure is necessary','reasonably necessary']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'extent_necessary',raw],[segment.get('unit')])
            if has_any(text,['subject to the provisions','bound by obligations of confidentiality','treat the confidential information as confidential','obligated to protect']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'confidentiality_bound',raw],[segment.get('unit')])
            if has_any(text,['written confidentiality agreement','written confidentiality agreements','written non-disclosure agreement','written nondisclosure agreement']):
                atoms_add(out,['source_disclosure_condition_atom',scope,segment.get('label',''),'written_confidentiality',raw],[segment.get('unit')])
        prohibited=has_any(text,['shall not disclose','not to disclose','not disclose it to anyone','not disclose the confidential information to any third party'])
        if prohibited and has_any(text,['anyone','third party','third parties']):
            cross=has_any(text,['unless this agreement expressly permits','except as expressly permitted','except as permitted under','except as provided under'])
            authorization=has_any(text,['prior written consent','express, prior written consent','prior written approval'])
            if cross and authorization:
                exception_kind='cross_reference_and_authorization'
            elif cross:
                exception_kind='unresolved_cross_reference'
            elif authorization:
                exception_kind='authorization'
            else:
                exception_kind='none'
            atoms_add(out,['source_clause_atom',scope,segment.get('label',''),segment.get('parent',''),'disclosure_prohibition',raw],[segment.get('unit')])
            atoms_add(out,['source_disclosure_prohibition_atom',scope,segment.get('label',''),exception_kind,raw],[segment.get('unit')])
            if cross:
                atoms_add(out,['source_reference_atom',scope,segment.get('label',''),'disclosure_permission_cross_reference',raw],[segment.get('unit')])
                unresolved.append('Disclosure permission cross-reference remains unresolved in clause '+segment.get('label',''))
        i+=1

def acquire_atoms(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    statements=[]
    unresolved=[]
    segments=atoms_segments(spans)
    atoms_emit_disclosure(segments,statements,unresolved)
    atoms_emit_disposal(segments,statements,unresolved)
    return {'statements':statements,'complete':len(atoms_unique(unresolved))==0,'unresolved':atoms_unique(unresolved)}

decision_functions:
def atoms_dec_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def atoms_dec_has(value,name):
    for item in atoms_dec_subterms(value):
        if item[0]==name:
            return True
    return False

def atoms_dec_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def atoms_dec_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    by_id={}
    for node in nodes:
        if isinstance(node,dict):
            by_id[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            node_id=todo.pop()
            if node_id in seen or node_id not in by_id:
                continue
            seen.add(node_id)
            node=by_id[node_id]
            for term in atoms_dec_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def atoms_dec_roles(value):
    tags=set()
    for item in atoms_dec_subterms(value):
        name=item[0]
        if name in ('employees_of','internal_personnel_of'):
            tags.add('employees')
            if len(item)>1 and atoms_dec_has(item[1],'controlled_entities_of'):
                tags.add('controlled_employees')
            else:
                tags.add('recipient_employees')
        elif name in ('independent_contractors_of','consultants_of','agents_of','professional_advisors_of','legal_advisors_of','financial_advisors_of','accountants_of','lenders_of'):
            tags.add('professionals')
        elif name=='third_parties':
            tags.add('third_parties')
    return tags

def atoms_dec_full_material(action):
    for item in atoms_dec_subterms(action):
        if item[0]=='source_scoped_disposal_material' and len(item)>1 and item[1] in ('confidential_information_and_copies','information_copies_and_derivatives','all_source_materials'):
            return True
        if item[0]=='information_bundle' and atoms_dec_has(item,'confidential_information') and atoms_dec_has(item,'copies_of'):
            return True
    return False

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=atoms_dec_entries(premises)
    if task in ('nda-5','nda-7'):
        permissions=[]
        prohibitions=[]
        relevant=[]
        for term,root in entries:
            if term[0] not in ('permission','prohibition') or len(term)<3:
                continue
            action=term[2]
            if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not atoms_dec_has(action[1],'confidential_information'):
                continue
            relevant.append(root)
            roles=atoms_dec_roles(action[2])
            if term[0]=='permission':
                permissions.append((root,roles))
            else:
                prohibitions.append((root,roles,action[2]))
        for root,roles in permissions:
            if task=='nda-5' and 'employees' in roles:
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
            if task=='nda-7' and roles.intersection({'professionals','third_parties'}):
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
        for root,roles,recipient in prohibitions:
            if atoms_dec_has(recipient,'outsiders_to'):
                continue
            if task=='nda-5' and 'employees' in roles:
                return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
            if task=='nda-7' and 'third_parties' in roles:
                return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
        if relevant:
            return {'handled':True,'answer':'NotMentioned','used_nodes':atoms_dec_unique(relevant)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    disposals=[]
    retention_permissions=[]
    retention_prohibitions=[]
    for term,root in entries:
        if term[0]=='disposal_obligation' and len(term)==5:
            disposals.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
    if task=='nda-16':
        endpoint=[]
        relevant=[]
        for term,root in disposals:
            if not (atoms_dec_has(term[2],'return_to') or atoms_dec_has(term[2],'destroy')):
                continue
            relevant.append(root)
            trigger=term[3]
            for item in atoms_dec_subterms(trigger):
                if item[0] in ('agreement_termination','project_termination','relationship_termination','service_termination','relationship_nonformation_deadline','purpose_completion'):
                    endpoint.append(root)
                if item[0]=='source_local_trigger' and len(item)>1 and item[1] in ('agreement_end','project_end','relationship_end','service_end','relationship_nonformation'):
                    endpoint.append(root)
        if endpoint:
            return {'handled':True,'answer':'Entailment','used_nodes':atoms_dec_unique(endpoint)}
        if relevant:
            return {'handled':True,'answer':'NotMentioned','used_nodes':atoms_dec_unique(relevant)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':atoms_dec_unique(retention_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':atoms_dec_unique(retention_prohibitions)}
    relevant=[]
    full=[]
    for term,root in disposals:
        if atoms_dec_has(term[2],'return_to') or atoms_dec_has(term[2],'destroy'):
            relevant.append(root)
            if atoms_dec_full_material(term[2]):
                full.append(root)
    if full:
        return {'handled':True,'answer':'Contradiction','used_nodes':atoms_dec_unique(full)}
    if relevant:
        return {'handled':True,'answer':'NotMentioned','used_nodes':atoms_dec_unique(relevant)}
    return {'handled':False,'answer':None,'used_nodes':[]}
